class Rectangle:
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

    def perimeter(self):
        return 2 * (self.width + self.height)

r = Rectangle(3, 4)
print(r.area())
print(r.perimeter())

class BankAccount:
    def __init__(self):
        self.balance = 0

    def deposit(self, n):
        self.balance += n

    def withdraw(self, n):
        if n <= self.balance:
            self.balance -= n

acc = BankAccount()
acc.deposit(150)
acc.withdraw(50)
print(acc.balance)
acc.withdraw(500)
print(acc.balance)
